function notePdfUrl(slug, { download = false } = {}) {
  const params = new URLSearchParams();
  if (download) params.set("download", "1");
  else params.set("ts", String(Date.now()));
  const query = params.toString();
  return `/api/mcp/interview-notes/${encodeURIComponent(slug)}/pdf${query ? `?${query}` : ""}`;
}

function updateNotePdfPreview({ slug, hasPdf, pdfFilename }) {
  selectedNoteHasPdf = Boolean(hasPdf);
  selectedNotePdfFilename = pdfFilename || "interview.pdf";

  const download = $("applyNoteDownloadPdf");
  const openPdf = $("applyNoteOpenPdf");
  if (download) {
    download.href = slug ? notePdfUrl(slug, { download: true }) : "#";
    download.download = selectedNotePdfFilename;
    download.hidden = !selectedNoteHasPdf;
  }
  if (openPdf) {
    openPdf.href = slug && selectedNoteHasPdf ? notePdfUrl(slug) : "#";
    openPdf.hidden = !selectedNoteHasPdf;
  }

  const pdfFrame = $("applyNotePdfFrame");
  const pdfMissing = $("applyNotePdfMissing");
  const renderBtn = $("applyNoteRenderBtn");

  if (renderBtn) renderBtn.disabled = !slug;

  if (selectedNoteHasPdf && slug && pdfFrame) {
    pdfFrame.hidden = false;
    pdfFrame.src = notePdfUrl(slug);
    if (pdfMissing) pdfMissing.hidden = true;
  } else {
    if (pdfFrame) {
      pdfFrame.removeAttribute("src");
      pdfFrame.hidden = true;
    }
    if (pdfMissing) pdfMissing.hidden = false;
  }
}

function renderNoteList() {
  const list = $("applyNoteList");
  if (!list) return;

  if (!noteItems.length) {
    list.innerHTML = `<li class="apply-master-empty">No interview notes yet — create one.</li>`;
    return;
  }

  list.innerHTML = noteItems.map((item) => {
    const label = (item.label || item.slug).trim();
    const active = item.slug === selectedNoteSlug ? " apply-master-item--active" : "";
    const pdfBadge = item.has_pdf
      ? '<span class="apply-master-item-badge apply-master-item-badge--pdf">PDF</span>'
      : "";
    return `<li><button type="button" class="apply-master-item${active}" data-slug="${escapeHtml(item.slug)}"><span class="apply-master-item-label">${escapeHtml(label)}${pdfBadge}</span><span class="apply-master-item-slug">${escapeHtml(item.slug)}</span></button></li>`;
  }).join("");
}

function clearNoteEditor() {
  selectedNoteSlug = "";
  selectedNoteHasPdf = false;
  selectedNotePdfFilename = "interview.pdf";
  $("applyNoteSlug").value = "";
  $("applyNoteLabel").value = "";
  $("applyNoteContent").value = "";
  $("applyNoteUpdated").textContent = "";
  updateNotePdfPreview({ slug: "", hasPdf: false });
  const pdfMissing = $("applyNotePdfMissing");
  if (pdfMissing) pdfMissing.hidden = false;
  renderNoteList();
}

async function loadNoteDetail(slug) {
  selectedNoteSlug = slug;
  renderNoteList();
  setLoadingProgress(20);
  try {
    const detail = await api(`/api/mcp/interview-notes/${encodeURIComponent(slug)}`);
    $("applyNoteSlug").value = detail.slug || slug;
    $("applyNoteLabel").value = detail.label || "";
    $("applyNoteContent").value = detail.content || "";
    const updatedParts = [];
    if (detail.updated_at) updatedParts.push(`Updated ${detail.updated_at}`);
    if (detail.pdf_updated_at) updatedParts.push(`PDF ${detail.pdf_updated_at}`);
    $("applyNoteUpdated").textContent = updatedParts.join(" · ");
    updateNotePdfPreview({
      slug: detail.slug || slug,
      hasPdf: detail.has_pdf,
      pdfFilename: detail.pdf_filename,
    });
  } finally {
    finishLoadingProgress();
  }
}

async function persistNote() {
  const slug = $("applyNoteSlug").value.trim();
  const content = $("applyNoteContent").value;
  if (!slug) {
    throw new Error("Slug is required (e.g. star)");
  }
  if (!content.trim()) {
    throw new Error("Interview notes cannot be empty");
  }

  const saved = await api(`/api/mcp/interview-notes/${encodeURIComponent(slug)}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      content,
      label: $("applyNoteLabel").value.trim(),
    }),
  });
  selectedNoteSlug = saved.slug || slug;
  const notesData = await api("/api/mcp/interview-notes");
  noteItems = notesData.items || [];
  renderNoteList();
  $("applyNoteUpdated").textContent = saved.updated_at
    ? `Updated ${saved.updated_at}`
    : "";
  return saved;
}

async function refreshNoteDetail(slug = selectedNoteSlug) {
  if (!slug) return null;
  const detail = await api(`/api/mcp/interview-notes/${encodeURIComponent(slug)}`);
  const updatedParts = [];
  if (detail.updated_at) updatedParts.push(`Updated ${detail.updated_at}`);
  if (detail.pdf_updated_at) updatedParts.push(`PDF ${detail.pdf_updated_at}`);
  $("applyNoteUpdated").textContent = updatedParts.join(" · ");
  updateNotePdfPreview({
    slug: detail.slug || slug,
    hasPdf: detail.has_pdf,
    pdfFilename: detail.pdf_filename,
  });
  return detail;
}

async function rerenderNotePdf() {
  const slug = $("applyNoteSlug").value.trim() || selectedNoteSlug;
  if (!slug) {
    showError("Select or save interview notes before rendering PDF");
    return;
  }

  const btn = $("applyNoteRenderBtn");
  const saveBtn = $("applyNoteSaveBtn");
  btn.disabled = true;
  if (saveBtn) saveBtn.disabled = true;
  showError("");
  beginScreenLoad("Rendering PDF…");
  setScreenLoadProgress(15);
  const tick = window.setInterval(() => setScreenLoadProgress(88), 800);
  try {
    setScreenLoadProgress(20);
    await persistNote();
    setScreenLoadProgress(35);
    const result = await api(
      `/api/mcp/interview-notes/${encodeURIComponent(selectedNoteSlug)}/render`,
      { method: "POST" },
    );
    setScreenLoadProgress(92);
    if (!result.ok) {
      throw new Error(result.error || result.log || "Render failed");
    }
    showToast("PDF re-rendered");
    updateNotePdfPreview({
      slug: selectedNoteSlug,
